action.code:
if (hash < 0.0f || hash > 1.0f) {
    LOG(FATAL) << "Hash value " << hash << " is out of the [0, 1] range";
}

SharedLock lk(partition_map_mx_);
if (partition_to_bucket_.empty()) {
    return nullptr;
}

auto it = partition_to_bucket_.upper_bound(hash);
if (it == partition_to_bucket_.end()) {
    return partition_to_bucket_.begin()->second;
}
return it->second;

